arguments.new_string:
def validate_sse_field(field_name: str):
    def validator(v: str | None) -> str | None:
        if v is not None:
            if "\\0" in v:
                raise ValueError(f"SSE '{field_name}' must not contain null characters")
            if "\\n" in v or "\\r" in v:
                raise ValueError(f"SSE '{field_name}' must not contain newlines")
        return v
    return validator

